import assert from 'node:assert/strict';
import { mkdir, writeFile, symlink } from 'node:fs/promises';
const fixture = '/private/tmp/security-path-example-x1fqiap0';
import { realpath, readFile } from 'node:fs/promises';
import { relative, isAbsolute, join, sep } from 'node:path';

const ALLOWED_ROOTS = [join(fixture, 'allowed-alias'), join(fixture, 'allowed', 'nested-root')];
const MIN_DEPTH = 1; // A root itself is never a cleanup target.

async function resolveCleanupCandidate(candidate, expectedOwner) {
  if (!isAbsolute(candidate) || !expectedOwner.trim()) throw new Error('invalid candidate');
  const roots = await Promise.all(ALLOWED_ROOTS.map((root) => realpath(root)));
  const target = await realpath(candidate);
  if (roots.includes(target)) throw new Error('refusing: allowed root itself');
  const inRoot = roots.some((root) => {
    const rel = relative(root, target);
    // Reject parent traversal, but permit an ordinary child named `..cache`.
    if (rel === '' || rel === '..' || rel.startsWith(`..${sep}`) || isAbsolute(rel)) return false;
    return rel.split(sep).length >= MIN_DEPTH;
  });
  if (!inRoot) throw new Error('refusing: outside allowed cleanup scope');
  const owner = await readFile(join(target, '.owner'), 'utf8').catch(() => null);
  if (owner?.trim() !== expectedOwner) throw new Error('refusing: owner mismatch or missing');
  return target; // Candidate only; do not pass directly to a destructive call.
}

for (const name of ['allowed', 'allowed/leaf', 'allowed/..cache', 'allowed/no-marker', 'allowed/wrong-owner', 'allowed/forged', 'allowed/nested-root', 'allowed-sibling', 'outside']) {
  await mkdir(join(fixture, name), { recursive: true });
}
for (const name of ['allowed/leaf', 'allowed/..cache', 'allowed/forged', 'allowed/nested-root', 'allowed-sibling', 'outside']) {
  await writeFile(join(fixture, name, '.owner'), 'job-123');
}
await writeFile(join(fixture, 'allowed/wrong-owner/.owner'), 'other-job');
await symlink(join(fixture, 'allowed'), join(fixture, 'allowed-alias'));
await symlink(join(fixture, 'outside'), join(fixture, 'allowed/escape'));
const results=[];
async function rejected(name, candidate) {
  await assert.rejects(resolveCleanupCandidate(candidate, 'job-123'));
  results.push({ name, result: 'rejected-as-required' });
}
await rejected('relative-input', 'allowed/leaf');
await rejected('root-itself', join(fixture, 'allowed'));
await rejected('nested-allowlisted-root', join(fixture, 'allowed/nested-root'));
await rejected('sibling-prefix', join(fixture, 'allowed-sibling'));
await rejected('symlink-escape', join(fixture, 'allowed/escape'));
await rejected('missing-marker', join(fixture, 'allowed/no-marker'));
await rejected('wrong-owner', join(fixture, 'allowed/wrong-owner'));
for (const name of ['leaf', '..cache']) {
  assert.equal(await resolveCleanupCandidate(join(fixture, 'allowed', name), 'job-123'), await realpath(join(fixture, 'allowed', name)));
  results.push({ name, result: 'candidate-returned' });
}
assert.equal(await resolveCleanupCandidate(join(fixture, 'allowed-alias/leaf'), 'job-123'), await realpath(join(fixture, 'allowed/leaf')));
results.push({ name: 'canonicalized-root-alias', result: 'candidate-returned' });
assert.equal(await resolveCleanupCandidate(join(fixture, 'allowed/forged'), 'job-123'), await realpath(join(fixture, 'allowed/forged')));
results.push({ name: 'forged-matching-marker', result: 'candidate-returned-as-documented-limitation-not-authorization' });
console.log(JSON.stringify({ checks: results.length, results, limitation: 'No deletion or race-resistance claim. Marker forgery deliberately passes the consistency-only example.' }, null, 2));

